namespace YomiYa.Features.Lootbar;

/// <summary>
/// Vista extendida del Lootbar con barra de herramientas y controles adicionales
/// </summary>
public partial class LootbarViewExtended : Avalonia.Controls.UserControl
{
    public LootbarViewExtended()
    {
        Avalonia.Markup.Xaml.AvaloniaXamlLoader.Load(this);
    }
}

using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

namespace YomiYa.Features.Lootbar;

/// <summary>
/// ViewModel extendido para Lootbar con funcionalidades avanzadas.
/// Descomenta las características que necesites.
/// </summary>
public partial class LootbarViewModelExtended : ViewModelBase
{
    /// <summary>
    /// URL de la tienda de Lootbar
    /// </summary>
    [ObservableProperty]
    private string _storeUrl = "https://www.lootbar.com/es/shop/streamifystore";

    /// <summary>
    /// Código de referencia del usuario (opcional)
    /// </summary>
    [ObservableProperty]
    private string _referralCode = "YomiYa";

    /// <summary>
    /// Indica si el WebView está cargando
    /// </summary>
    [ObservableProperty]
    private bool _isLoading;

    /// <summary>
    /// Título de la página actual
    /// </summary>
    [ObservableProperty]
    private string _pageTitle = "Lootbar Store";

    /// <summary>
    /// Historial de navegación
    /// </summary>
    [ObservableProperty]
    private bool _canGoBack;

    [ObservableProperty]
    private bool _canGoForward;

    /// <summary>
    /// Nivel de zoom del WebView
    /// </summary>
    [ObservableProperty]
    private double _zoomLevel = 1.0;

    public LootbarViewModelExtended()
    {
        // Inicialización básica
    }

    /// <summary>
    /// Abre la tienda con un código de referencia específico
    /// </summary>
    public void OpenStoreWithCode(string code)
    {
        ReferralCode = code;
        StoreUrl = $"https://www.lootbar.com/es/shop/{code}";
    }

    /// <summary>
    /// Recarga la página actual
    /// </summary>
    [RelayCommand]
    private void ReloadPage()
    {
        // El WebView se recarga automáticamente si asignamos la misma URL
        var currentUrl = StoreUrl;
        StoreUrl = "about:blank";
        StoreUrl = currentUrl;
    }

    /// <summary>
    /// Restablece el zoom a nivel normal
    /// </summary>
    [RelayCommand]
    private void ResetZoom()
    {
        ZoomLevel = 1.0;
    }

    /// <summary>
    /// Aumenta el zoom
    /// </summary>
    [RelayCommand]
    private void ZoomIn()
    {
        if (ZoomLevel < 2.0)
            ZoomLevel += 0.1;
    }

    /// <summary>
    /// Disminuye el zoom
    /// </summary>
    [RelayCommand]
    private void ZoomOut()
    {
        if (ZoomLevel > 0.5)
            ZoomLevel -= 0.1;
    }

    protected override void UpdateLocalizedTexts()
    {
        // Localización opcional
        PageTitle = "Lootbar Store";
    }
}
